# Bank zadań autorskich — etap 2: wypracowania (partia 2: XVIII w., XIX w., 1914–1939).
BANK = {}

M = 'Wypracowanie (wypowiedź argumentacyjna). Zadanie autorskie IndexLab w formacie egzaminu maturalnego od 2023 r. Twoja wypowiedź powinna liczyć minimum 300 wyrazów.'

BANK['umiejetnosci'] = [
 B('Wypracowanie — XVIII w.: reformy stanisławowskie', M,
   T('wypracowanie', 15, 'Reformy przeprowadzone w Rzeczypospolitej w latach 1764–1792 mogły uratować państwo przed upadkiem. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt ustrojowy, społeczno-gospodarczy i międzynarodowy.',
     'Modelowa odpowiedź (stanowisko: reformy mogły wzmocnić państwo, ale nie mogły go uratować bez sprzyjającej sytuacji międzynarodowej).\n\n'
     'Panowanie Stanisława Augusta Poniatowskiego (1764–1795) przyniosło najbardziej ambitny program naprawy państwa w dziejach Rzeczypospolitej. Uważam, że reformy realnie wzmacniały kraj, ale same w sobie nie mogły go uratować, bo o losie Rzeczypospolitej decydowały ostatecznie silniejsze od niej mocarstwa.\n\n'
     'W aspekcie ustrojowym zmiany były głębokie. Już w 1764 r. ograniczono liberum veto w sprawach skarbowych, a w 1775 r. powołano Radę Nieustającą — pierwszy stały rząd. Sejm Wielki (1788–1792) uchwalił Konstytucję 3 maja, która znosiła liberum veto i wolną elekcję, wprowadzała trójpodział władzy i dziedziczność tronu. Ustawa o miastach dawała mieszczanom prawo nabywania ziemi i udział w sejmie. Gdyby te zasady zdążyły wejść w życie, Rzeczpospolita stałaby się sprawną monarchią konstytucyjną.\n\n'
     'W aspekcie społeczno-gospodarczym rozwijały się manufaktury, mennica i nowe drogi, a Komisja Edukacji Narodowej (1773) stworzyła pierwszy w Europie świecki system szkolnictwa państwowego. Szkoła Rycerska kształciła oficerów, a uchwalone przez Sejm Wielki aukcja wojska (100 tys. żołnierzy) i stałe podatki miały zapewnić państwu siłę. Zabrakło jednak czasu i pieniędzy, a położenie chłopów konstytucja zmieniła tylko symbolicznie, biorąc ich „pod opiekę prawa”.\n\n'
     'Decydujący był aspekt międzynarodowy. Reformy przeprowadzano po I rozbiorze (1772), pod czujnym okiem Rosji, która gwarantowała dawny ustrój. Sejm Wielki wykorzystał chwilowe zaangażowanie Rosji w wojnę z Turcją i sojusz z Prusami (1790), ale gdy wojna się skończyła, Katarzyna II poparła konfederację targowicką. Prusy zerwały sojusz, a wojna w obronie Konstytucji (1792) zakończyła się kapitulacją króla i II rozbiorem.\n\n'
     'Można argumentować, że gdyby reformy przeprowadzono kilkadziesiąt lat wcześniej, za Sasów, gdy sąsiedzi byli zajęci innymi wojnami, Rzeczpospolita miałaby czas, by się wzmocnić. W latach 1788–1792 była już jednak zbyt słaba wojskowo i finansowo, by obronić zmiany przeciw Rosji i Prusom jednocześnie.\n\n'
     'Podsumowując, reformy stanisławowskie były potrzebne i dalekowzroczne, a ich dziedzictwo — zwłaszcza Konstytucja 3 maja i KEN — przetrwało rozbiory. Nie mogły jednak same uratować państwa, którego los zależał od woli mocarstw.',
     'Plan: stanowisko „wzmacniały, ale nie mogły uratować” → ustrojowy (1764, Rada Nieustająca, Konstytucja 3 maja, ustawa o miastach) → społeczno-gospodarczy (KEN, manufaktury, aukcja wojska, sprawa chłopska) → międzynarodowy (Rosja, sojusz z Prusami, Targowica, 1792, II rozbiór) → kontrargument „za późno” → wniosek.\n\nTypowe błędy: pisanie, że Konstytucja 3 maja zniosła pańszczyznę (nie zniosła); pomijanie roli Prus.')),

 B('Wypracowanie — XVIII w.: rewolucja francuska', M,
   T('wypracowanie', 15, 'Rewolucja francuska przyniosła Europie więcej korzyści niż strat. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, społeczny i militarny.',
     'Modelowa odpowiedź (stanowisko: w perspektywie długofalowej teza jest prawdziwa, choć koszty ludzkie były ogromne).\n\n'
     'Rewolucja francuska, rozpoczęta zdobyciem Bastylii w lipcu 1789 r., obaliła monarchię absolutną w jednym z najpotężniejszych państw Europy. Przez dekadę wstrząsała Francją, a później — przez wojny — całym kontynentem. Uważam, że w dłuższej perspektywie przyniosła Europie więcej korzyści niż strat, choć jej przebieg był krwawy.\n\n'
     'W aspekcie politycznym rewolucja ogłosiła zasady, które stały się fundamentem nowoczesnych państw. Deklaracja praw człowieka i obywatela (1789) głosiła wolność, równość wobec prawa, suwerenność narodu i trójpodział władzy. Konstytucja z 1791 r. uczyniła Francję monarchią konstytucyjną, a w 1792 r. proklamowano republikę. Kosztem był jednak terror jakobinów (1793–1794), w czasie którego zgilotynowano tysiące ludzi, w tym króla Ludwika XVI, a rewolucja zakończyła się dyktaturą Napoleona.\n\n'
     'W aspekcie społecznym rewolucja zniosła przywileje stanowe i feudalne powinności chłopów, a majątki Kościoła upaństwowiono i sprzedano. Wprowadzono równość wobec prawa, a później Kodeks Napoleona (1804), który utrwalił te zasady i rozszedł się po Europie, m.in. do Księstwa Warszawskiego. Zarazem rewolucja wywołała wojnę domową w Wandei, gdzie zginęły dziesiątki tysięcy ludzi.\n\n'
     'W aspekcie militarnym rewolucja zapoczątkowała ponad dwudziestoletni okres wojen. Pobór powszechny (levée en masse) stworzył masowe armie, a wojny napoleońskie kosztowały życie kilku milionów ludzi. Z drugiej strony przemarsze armii francuskiej niosły ze sobą nowe prawo i idee, budziły ruchy narodowe — także polskie (Legiony Dąbrowskiego, Księstwo Warszawskie).\n\n'
     'Przeciwnicy tezy, jak Edmund Burke, już w czasie rewolucji ostrzegali, że gwałtowne zrywanie z tradycją prowadzi do chaosu i tyranii — i przebieg terroru zdawał się przyznawać im rację. Jednak idee rewolucji przetrwały restaurację Burbonów i kongres wiedeński, a w XIX w. stopniowo zmieniały ustroje kolejnych państw.\n\n'
     'Warto też pamiętać, że rewolucja wprowadziła system metryczny, świeckie śluby i rejestrację urodzeń przez państwo, a w 1794 r. zniosła niewolnictwo w koloniach (przywrócone później przez Napoleona) — to zmiany, które przetrwały w wielu krajach do dziś.\n\n'
     'Podsumowując, rewolucja francuska była okresem wielkich ofiar, ale jej najważniejsze dziedzictwo — prawa człowieka, równość wobec prawa i suwerenność narodu — stało się podstawą współczesnej Europy. Dlatego uważam tezę za prawdziwą.',
     'Plan: stanowisko „tak, mimo ofiar” → polityczny (Deklaracja 1789, konstytucja 1791, republika, ale terror) → społeczny (zniesienie przywilejów, Kodeks Napoleona, ale Wandea) → militarny (wojny, levée en masse, ale idee i ruchy narodowe) → kontrargument (Burke) → wniosek.\n\nTypowe błędy: kończenie opisu na 1789 r.; brak związku z ziemiami polskimi — warto go wpleść.')),

 B('Wypracowanie — XIX w.: powstanie listopadowe', M,
   T('wypracowanie', 15, 'Powstanie listopadowe miało realne szanse na zwycięstwo. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt militarny, polityczny i międzynarodowy.',
     'Modelowa odpowiedź (stanowisko: szanse istniały na początku powstania, ale zostały zmarnowane i szybko zmalały).\n\n'
     'Powstanie listopadowe wybuchło 29 listopada 1830 r. jako spisek podchorążych, a przekształciło się w regularną wojnę Królestwa Polskiego z Rosją. Uważam, że w pierwszych miesiącach miało ono pewne szanse przynajmniej na kompromis z carem, ale z powodu błędów przywódców i braku pomocy z zagranicy szanse te szybko zniknęły.\n\n'
     'W aspekcie militarnym Królestwo miało przewagę, jakiej nie miało żadne późniejsze powstanie: regularną, dobrze wyszkoloną armię liczącą kilkadziesiąt tysięcy żołnierzy, arsenały i zaplecze państwa. Wojsko polskie odniosło sukcesy pod Olszynką Grochowską (luty 1831), Wawrem, Dębem Wielkim i Iganiami. Jednak dowódcy — Chłopicki, Radziwiłł, Skrzynecki — nie wierzyli w zwycięstwo i unikali decydującej ofensywy, gdy Rosjanie byli rozproszeni. Klęska pod Ostrołęką (maj 1831) przesądziła o losie wojny.\n\n'
     'W aspekcie politycznym przywódcy powstania byli podzieleni. Obóz zachowawczy (Czartoryski, Chłopicki) liczył na ugodę z carem, a radykałowie (Lelewel, Towarzystwo Patriotyczne) chcieli wojny totalnej. Detronizacja Mikołaja I (25 stycznia 1831) wykluczyła kompromis, ale nie towarzyszyły jej reformy społeczne: sejm nie uwłaszczył chłopów, więc nie udało się pozyskać ludu do masowej walki.\n\n'
     'W aspekcie międzynarodowym powstańcy liczyli na pomoc Francji i Wielkiej Brytanii. Mocarstwa ograniczyły się jednak do wyrazów sympatii, a Prusy i Austria utrudniały powstańcom zaopatrzenie i pomagały Rosji. Rozszerzenie powstania na Litwę, Wołyń i Podole nie zmieniło sytuacji, bo walki tam były słabo przygotowane.\n\n'
     'Zwolennicy przeciwnego stanowiska podkreślają ogromną przewagę Rosji — liczebną i gospodarczą — która w wojnie trwającej dłużej musiała zwyciężyć. To prawda, ale celem nie musiało być pokonanie Rosji, lecz wymuszenie ustępstw, a na to szanse istniały na początku 1831 r.\n\n'
     'Warto dodać, że szansą był też czas: Rosja potrzebowała kilku miesięcy, by przerzucić główne siły, a epidemia cholery w 1831 r. osłabiała jej armię. Polskie dowództwo nie wykorzystało tych miesięcy na zdecydowane uderzenie, gdy przewaga przeciwnika nie była jeszcze przytłaczająca.\n\n'
     'Podsumowując, powstanie listopadowe miało ograniczone, ale realne szanse na wywalczenie korzystnego kompromisu. Zmarnowały je bierność dowódców, brak reform społecznych i obojętność Europy. Teza jest więc prawdziwa tylko w odniesieniu do pierwszych miesięcy powstania.',
     'Plan: stanowisko „szanse na początku, zmarnowane” → militarny (regularna armia, Grochów, Wawer, Iganie, bierność dowódców, Ostrołęka) → polityczny (podziały, detronizacja, brak uwłaszczenia) → międzynarodowy (bierność Francji i Wielkiej Brytanii, Prusy i Austria) → kontrargument (przewaga Rosji) → wniosek.\n\nTypowe błędy: opis przebiegu bitew bez oceny szans; mylenie z powstaniem styczniowym (to w 1863 r. walczyły oddziały partyzanckie).')),

 B('Wypracowanie — XIX w.: praca organiczna a powstania', M,
   T('wypracowanie', 15, 'W drugiej połowie XIX w. praca organiczna była dla Polaków skuteczniejszą drogą obrony narodu niż walka zbrojna. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji sytuację w trzech zaborach.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa dla okresu 1864–1904).\n\n'
     'Po klęsce powstania styczniowego (1864) wśród Polaków zwyciężyło przekonanie, że kolejny zryw przyniósłby tylko represje. Pozytywiści postawili na pracę organiczną — rozwój gospodarki, instytucji i oświaty. Uważam, że w ówczesnych warunkach była to droga skuteczniejsza niż walka zbrojna, bo pozwoliła zachować i wzmocnić naród do czasu, gdy pojawiła się realna szansa na niepodległość.\n\n'
     'Najlepszym przykładem jest zabór pruski. Państwo pruskie prowadziło politykę germanizacji: Kulturkampf (1871–1878), rugi (1885), Komisja Kolonizacyjna (1886), a w 1908 r. ustawa wywłaszczeniowa. Polacy odpowiedzieli pracą organiczną: Hipolit Cegielski budował przedsiębiorstwa, Karol Marcinkowski — instytucje wspierające młodzież, a ks. Piotr Wawrzyniak rozwijał sieć banków ludowych i spółdzielni. Dzięki temu Polacy nie tylko nie stracili ziemi, ale w wielu powiatach powiększyli swój stan posiadania.\n\n'
     'W zaborze rosyjskim po 1864 r. nastąpiła rusyfikacja: likwidacja odrębności Królestwa, rosyjski w szkołach i urzędach. Walka zbrojna nie miała szans, więc działano inaczej: rozwijał się przemysł (Łódź, Zagłębie), a tajne nauczanie i Uniwersytet Latający podtrzymywały polską kulturę. Pozytywiści — Bolesław Prus, Eliza Orzeszkowa, Aleksander Świętochowski — propagowali pracę u podstaw, czyli oświatę ludu.\n\n'
     'W Galicji, dzięki autonomii (po 1867 r.), praca organiczna mogła działać jawnie: polskie szkoły, uniwersytety w Krakowie i Lwowie, Akademia Umiejętności (1872), Sejm Krajowy. Galicja stała się „polskim Piemontem” — ośrodkiem kultury i, później, organizacji niepodległościowych.\n\n'
     'Zwolennicy przeciwnego poglądu podkreślają, że sama praca organiczna nie przywróciła niepodległości, a pamięć o powstaniach podtrzymywała ducha narodu. Rzeczywiście, Legiony i walka zbrojna w czasie I wojny światowej były konieczne w 1914–1918 r. Ale walczyć mogło już społeczeństwo silniejsze, wykształcone i zorganizowane właśnie dzięki pracy organicznej.\n\n'
     'Pozytywizm miał też wymiar społeczny: walczył o równouprawnienie kobiet i Żydów, rozwijał opiekę nad biednymi i oświatę dorosłych. Dzięki temu w społeczeństwie polskim wzrosła liczba ludzi wykształconych, zamożnych i świadomych narodowo — także wśród chłopów, którzy wcześniej często byli obojętni wobec sprawy polskiej.\n\n'
     'Podsumowując, w latach 1864–1904 praca organiczna była skuteczniejsza niż walka zbrojna, bo chroniła naród przed wynarodowieniem i przygotowała go do odzyskania niepodległości. Teza jest więc prawdziwa w odniesieniu do tego okresu.',
     'Plan: stanowisko „tak, w latach 1864–1904” → zabór pruski (polityka germanizacji vs Cegielski, Marcinkowski, Wawrzyniak) → zabór rosyjski (rusyfikacja vs przemysł, tajne nauczanie, pozytywiści) → Galicja (autonomia, instytucje, „polski Piemont”) → kontrargument (powstania i Legiony) → wniosek.\n\nTypowe błędy: mylenie pracy organicznej (gospodarka, instytucje) z pracą u podstaw (oświata ludu); opisywanie tylko jednego zaboru, gdy temat wymaga trzech.')),

 B('Wypracowanie — XIX w.: zjednoczenie Niemiec', M,
   T('wypracowanie', 15, 'Zjednoczenie Niemiec w 1871 r. zasadniczo zmieniło układ sił w Europie. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, militarny i gospodarczy.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa).\n\n'
     'Proklamacja Cesarstwa Niemieckiego w Wersalu 18 stycznia 1871 r. zakończyła proces zjednoczenia prowadzony przez Prusy pod kierunkiem Ottona von Bismarcka. Uważam, że to wydarzenie zasadniczo zmieniło układ sił w Europie: w jej centrum powstało najsilniejsze państwo kontynentu, co zburzyło równowagę ustaloną na kongresie wiedeńskim.\n\n'
     'W aspekcie politycznym zjednoczenie dokonało się „krwią i żelazem” — przez wojny z Danią (1864), Austrią (1866) i Francją (1870–1871). Austria została wyparta ze spraw niemieckich i przekształciła się w Austro-Węgry, a Francja, upokorzona proklamacją cesarstwa w Wersalu, straciła Alzację i Lotaryngię. Od tej pory wrogość francusko-niemiecka stała się stałym elementem polityki europejskiej. Bismarck budował system sojuszy (Związek Trzech Cesarzy, trójprzymierze z 1882 r.), by izolować Francję.\n\n'
     'W aspekcie militarnym Niemcy dysponowały najlepiej zorganizowaną armią lądową Europy, opartą na powszechnym poborze i sprawnym sztabie generalnym, co pokazała szybka klęska Francji pod Sedanem. Za Wilhelma II (po 1890 r.) Niemcy rozpoczęły rozbudowę floty wojennej, co doprowadziło do wyścigu zbrojeń z Wielką Brytanią i zbliżenia Londynu z Paryżem (entente cordiale, 1904).\n\n'
     'W aspekcie gospodarczym zjednoczone Niemcy dysponowały wspólnym rynkiem, węglem z Zagłębia Ruhry i Śląska oraz kontrybucją wypłaconą przez Francję. W ciągu kilkudziesięciu lat wyprzedziły Wielką Brytanię w produkcji stali i stały się liderem przemysłu chemicznego i elektrotechnicznego. Siła gospodarcza wzmacniała ambicje polityczne — Niemcy domagały się „miejsca pod słońcem”, czyli kolonii.\n\n'
     'Można argumentować, że już wcześniej Prusy były mocarstwem, a zjednoczenie jedynie potwierdziło ich pozycję. Jednak dopiero połączenie państw niemieckich stworzyło potęgę, która mogła rzucić wyzwanie Wielkiej Brytanii i Rosji jednocześnie.\n\n'
     'Zmiana układu sił była widoczna także na kongresie berlińskim (1878), gdzie Bismarck występował jako „uczciwy makler” w sporze Rosji z Wielką Brytanią i Austro-Węgrami o Bałkany. Berlin stał się stolicą europejskiej dyplomacji, a rozczarowana Rosja zaczęła z czasem szukać porozumienia z Francją — sojusz zawarto w latach 1892–1894.\n\n'
     'Podsumowując, zjednoczenie Niemiec zburzyło dawną równowagę sił: doprowadziło do trwałej wrogości z Francją, powstania bloków polityczno-wojskowych i wyścigu zbrojeń. W ten sposób pośrednio przygotowało grunt pod I wojnę światową.',
     'Plan: stanowisko „tak” → polityczny (trzy wojny, Austria wyparta, Alzacja i Lotaryngia, sojusze Bismarcka) → militarny (armia, Sedan, flota Wilhelma II) → gospodarczy (rynek, węgiel, stal, chemia, kolonie) → kontrargument (Prusy już były mocarstwem) → wniosek z powiązaniem z 1914 r.\n\nTypowe błędy: pomijanie Austrii; brak powiązania z genezą I wojny światowej, które jest najmocniejszym argumentem.')),

 B('Wypracowanie — 1914–1939: traktat wersalski', M,
   T('wypracowanie', 15, 'Postanowienia traktatu wersalskiego zapowiadały kolejny konflikt zbrojny w Europie. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt terytorialny, militarny i gospodarczy.',
     'Modelowa odpowiedź (stanowisko: teza jest częściowo prawdziwa — traktat stworzył napięcia, ale wojnę wywołała polityka lat 30.).\n\n'
     'Traktat wersalski, podpisany 28 czerwca 1919 r., kończył I wojnę światową z Niemcami. Francuski marszałek Foch miał powiedzieć, że to „nie pokój, lecz rozejm na dwadzieścia lat”. Uważam, że traktat rzeczywiście zawierał zarzewie przyszłego konfliktu, ale nie przesądzał o nim — o wybuchu wojny zdecydowała dopiero polityka Hitlera i ustępliwość mocarstw.\n\n'
     'W aspekcie terytorialnym Niemcy straciły Alzację i Lotaryngię na rzecz Francji, Wielkopolskę i Pomorze na rzecz Polski, a Gdańsk stał się Wolnym Miastem. Prusy Wschodnie zostały oddzielone od reszty kraju „korytarzem”. Niemcy uznały te straty za niesprawiedliwe, a hasło rewizji granic stało się podstawą programu wielu partii, zwłaszcza NSDAP. Jednocześnie dla Polaków i Francuzów zmiany te były przywróceniem sprawiedliwości.\n\n'
     'W aspekcie militarnym traktat ograniczył armię niemiecką do 100 tys. żołnierzy, zakazał lotnictwa wojskowego, czołgów i okrętów podwodnych, a Nadrenię zdemilitaryzowano. Ograniczenia te były upokarzające, ale nie zniszczyły niemieckiego potencjału: Niemcy po cichu omijały zakazy (współpraca z ZSRS po Rapallo, 1922), a w latach 30. otwarcie je łamały — wprowadzenie poboru (1935) i remilitaryzacja Nadrenii (1936) spotkały się tylko z protestami.\n\n'
     'W aspekcie gospodarczym Niemcy obarczono odpowiedzialnością za wojnę i ogromnymi reparacjami. Brytyjski ekonomista John Maynard Keynes ostrzegał, że zrujnują one Niemcy i całą Europę. Hiperinflacja z 1923 r., a później wielki kryzys (od 1929 r.) zubożyły społeczeństwo i ułatwiły Hitlerowi dojście do władzy w 1933 r.\n\n'
     'Z drugiej strony traktat nie był tak surowy, by uniemożliwić Niemcom powrót do potęgi — pozostawił je największym państwem Europy Środkowej. Reparacje zredukowano (plan Dawesa, plan Younga), a w 1925 r. w Locarno Niemcy dobrowolnie uznały swoją granicę zachodnią. Pokój mógł przetrwać, gdyby mocarstwa konsekwentnie broniły jego postanowień.\n\n'
     'Warto dodać, że nowy ład osłabiała też nieobecność Stanów Zjednoczonych w Lidze Narodów oraz izolacja Rosji Sowieckiej. System wersalski od początku nie miał więc gwarantów zdolnych i gotowych go bronić, co Hitler potrafił wykorzystać.\n\n'
     'Podsumowując, traktat wersalski stworzył poczucie krzywdy, które wykorzystali naziści, więc teza jest częściowo prawdziwa. Wojnę wywołała jednak dopiero decyzja Hitlera, ułatwiona polityką ustępstw Zachodu.',
     'Plan: stanowisko „częściowo” → terytorialny (Alzacja, Wielkopolska, Pomorze, Gdańsk, korytarz, rewizjonizm) → militarny (100 tys., zakazy, obchodzenie, 1935, 1936) → gospodarczy (reparacje, Keynes, 1923, kryzys, 1933) → kontrargument (Locarno, redukcja reparacji, appeasement) → wniosek.\n\nTypowe błędy: obarczanie traktatu wyłączną winą za II wojnę światową; brak dat łamania traktatu.')),

 B('Wypracowanie — 1914–1939: II Rzeczpospolita', M,
   T('wypracowanie', 15, 'W latach 1918–1939 Polska odniosła więcej sukcesów niż porażek. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, gospodarczy i społeczno-kulturowy.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa, choć II RP nie poradziła sobie z wieloma problemami).\n\n'
     'II Rzeczpospolita powstała w 1918 r. z trzech zaborów, różniących się prawem, walutą, koleją i poziomem rozwoju. Przetrwała zaledwie dwadzieścia lat. Uważam, że mimo krótkiego czasu i ogromnych trudności przyniosła więcej sukcesów niż porażek, bo zbudowała od podstaw sprawne państwo, a jej osiągnięcia przetrwały nawet okres PRL.\n\n'
     'W aspekcie politycznym największym sukcesem było obronienie niepodległości i granic. Zwycięstwo w wojnie z bolszewikami (bitwa warszawska, sierpień 1920) i pokój ryski (1921) ustaliły granicę wschodnią, a powstania wielkopolskie i śląskie przyniosły ziemie na zachodzie. Ujednolicono administrację i prawo, wprowadzono konstytucję (1921). Porażką była niestabilność polityczna: zabójstwo prezydenta Narutowicza (1922), częste zmiany rządów i przewrót majowy (1926), po którym rządy sanacji ograniczyły demokrację (proces brzeski, Bereza Kartuska).\n\n'
     'W aspekcie gospodarczym reforma Władysława Grabskiego (1924) zakończyła hiperinflację i wprowadziła złotego. Zbudowano port w Gdyni, który w kilkanaście lat stał się jednym z największych portów Bałtyku, magistralę węglową i Centralny Okręg Przemysłowy (od 1936 r.) — dzieła Eugeniusza Kwiatkowskiego. Słabością pozostawało przeludnienie i bieda wsi, a wielki kryzys (1929–1935) uderzył w Polskę wyjątkowo mocno.\n\n'
     'W aspekcie społeczno-kulturowym zbudowano powszechny system szkolny i zmniejszono analfabetyzm; rozwijały się uniwersytety, nauka (lwowska szkoła matematyczna) i kultura. Polscy kryptolodzy złamali szyfr Enigmy. Kobiety uzyskały prawa wyborcze już w 1918 r. Problemem pozostawały napięcia z mniejszościami narodowymi — stanowiącymi około jednej trzeciej ludności — zwłaszcza z Ukraińcami (pacyfikacja Małopolski Wschodniej, 1930).\n\n'
     'Krytycy podkreślają, że II RP przegrała w 1939 r. wojnę i nie zdołała się obronić. Jednak klęska wynikała z przewagi dwóch agresorów — III Rzeszy i ZSRS — a nie tylko ze słabości państwa.\n\n'
     'Sukcesem było też zjednoczenie trzech sieci kolejowych, trzech systemów prawnych i sześciu walut w jedno sprawne państwo w ciągu kilku lat — bez tego żadne późniejsze osiągnięcia gospodarcze nie byłyby możliwe.\n\n'
     'Podsumowując, II Rzeczpospolita zbudowała państwo z trzech różnych części, obroniła niepodległość i stworzyła nowoczesne instytucje. Teza jest więc prawdziwa, choć nie można pomijać kryzysu demokracji i problemów społecznych.',
     'Plan: stanowisko „tak” → polityczny (1920, Ryga, ujednolicenie, konstytucja / porażki: Narutowicz, 1926, Brześć, Bereza) → gospodarczy (Grabski, Gdynia, COP / wieś i kryzys) → społeczno-kulturowy (szkolnictwo, nauka, Enigma, prawa kobiet / mniejszości) → kontrargument (1939) → wniosek.\n\nTypowe błędy: wymienianie samych sukcesów bez porażek (temat wymaga bilansu); mylenie reform Grabskiego z inwestycjami Kwiatkowskiego.')),

 B('Wypracowanie — 1914–1939: polityka ustępstw', M,
   T('wypracowanie', 15, 'Polityka ustępstw mocarstw zachodnich wobec III Rzeszy była główną przyczyną wybuchu II wojny światowej. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, militarny i ideologiczny.',
     'Modelowa odpowiedź (stanowisko: polityka ustępstw była ważną, ale nie główną przyczyną — główną była agresywna polityka Hitlera).\n\n'
     'We wrześniu 1938 r. premier Wielkiej Brytanii Neville Chamberlain wrócił z Monachium, ogłaszając „pokój dla naszych czasów”. Rok później wybuchła najkrwawsza wojna w dziejach. Polityka ustępstw (appeasement) bez wątpienia ułatwiła Hitlerowi drogę, ale uważam, że główną przyczyną wojny była sama ideologia i polityka III Rzeszy, której celem był podbój.\n\n'
     'W aspekcie politycznym mocarstwa zachodnie wielokrotnie godziły się na łamanie ładu wersalskiego. Nie zareagowały na wprowadzenie poboru w Niemczech (1935), remilitaryzację Nadrenii (1936) ani Anschluss Austrii (marzec 1938). W Monachium Wielka Brytania i Francja zgodziły się na oddanie Niemcom Sudetów bez udziału Czechosłowacji, a w marcu 1939 r. Hitler zajął resztę Czech. Każde ustępstwo przekonywało go, że Zachód nie będzie walczył. Pakt Ribbentrop–Mołotow (23 sierpnia 1939) z tajnym protokołem o podziale Europy Wschodniej był ostatnim krokiem przed agresją.\n\n'
     'W aspekcie militarnym polityka ustępstw miała swoje racje: Wielka Brytania i Francja były do wojny nieprzygotowane, a społeczeństwa pamiętały rzeź I wojny światowej. Zyskany czas Brytyjczycy wykorzystali na rozbudowę lotnictwa, co pomogło im w 1940 r. Jednak Niemcy zbroiły się szybciej, a zajęcie Czechosłowacji dało im jej zakłady zbrojeniowe (Škoda) i zniszczyło dobrze ufortyfikowanego sojusznika Francji.\n\n'
     'Decydujący był jednak aspekt ideologiczny. Program Hitlera, przedstawiony już w „Mein Kampf”, zakładał zdobycie „przestrzeni życiowej” na Wschodzie, podporządkowanie Słowian i rasową przebudowę Europy. Takich celów nie dało się zaspokoić ustępstwami — Hitler dążył do wojny, a kolejne zdobycze traktował jako etapy. Także ZSRS miał własne cele ekspansji, czego dowodem była agresja 17 września 1939 r.\n\n'
     'Zwolennicy tezy przekonują, że stanowcza reakcja w 1936 r., gdy Wehrmacht był jeszcze słaby, mogła obalić Hitlera. To możliwe, ale nie zmienia faktu, że inicjatorem wojny była III Rzesza — ustępstwa jedynie ułatwiły jej realizację planów.\n\n'
     'Podsumowując, appeasement był błędem, który przybliżył wojnę i pogorszył położenie przyszłych ofiar, w tym Polski. Główną przyczyną II wojny światowej była jednak agresywna, rasistowska ideologia i polityka III Rzeszy, wsparta w 1939 r. przez ZSRS.',
     'Plan: stanowisko „ważna, ale nie główna przyczyna” → polityczny (1935, 1936, Anschluss, Monachium, marzec 1939, pakt 23 VIII) → militarny (racje appeasementu, zbrojenia, Škoda) → ideologiczny (Mein Kampf, Lebensraum, plany ZSRS) → kontrargument (reakcja w 1936) → wniosek.\n\nTypowe błędy: pisanie tylko o Monachium; pomijanie paktu Ribbentrop–Mołotow; mylenie Anschlussu (Austria) z aneksją Sudetów.')),
]
